import{_ as a,o,c as r,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"5.7 主令电器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-7-zhu-ling-dian-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-7-zhu-ling-dian-qi.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-7-zhu-ling-dian-qi.md"};function e(n,t,s,d,h,u){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-7-主令电器" tabindex="-1">5.7 主令电器 <a class="header-anchor" href="#_5-7-主令电器" aria-label="Permalink to &quot;5.7 主令电器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;主令电器&quot;就是给人&quot;发命令&quot;的电器——按钮、行程开关、转换开关、刀开关。它们不直接控制大电流,而是把人的动作或机械位置变成电信号,指挥接触器、继电器动作。这一节逐个认识。</p><h2 id="一、按钮" tabindex="-1">一、按钮 <a class="header-anchor" href="#一、按钮" aria-label="Permalink to &quot;一、按钮&quot;">​</a></h2><p>按钮是<strong>手动操作</strong>的主令电器,用于发出启动、停止命令。</p><h3 id="_1-种类-按触点分" tabindex="-1">1. 种类(按触点分) <a class="header-anchor" href="#_1-种类-按触点分" aria-label="Permalink to &quot;1. 种类(按触点分)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>断电状态</th><th>用途</th></tr></thead><tbody><tr><td><strong>常开按钮(启动按钮)</strong></td><td>断开</td><td>按下闭合,用于&quot;启动&quot;</td></tr><tr><td><strong>常闭按钮(停止按钮)</strong></td><td>闭合</td><td>按下断开,用于&quot;停止&quot;</td></tr><tr><td><strong>复合按钮</strong></td><td>—</td><td>同时含常开、常闭两对触头,按下时一路闭合一路断开</td></tr></tbody></table><h3 id="_2-颜色规定-必背" tabindex="-1">2. 颜色规定(必背) <a class="header-anchor" href="#_2-颜色规定-必背" aria-label="Permalink to &quot;2. 颜色规定(必背)&quot;">​</a></h3><ul><li><strong>红色按钮</strong>:停止、急停;</li><li><strong>绿色按钮</strong>:启动;</li><li>黄色等其他颜色可用于点动等。</li></ul><blockquote><p>💡 口诀:<strong>&quot;红停绿启&quot;</strong>——和交通灯相反,别记错。</p></blockquote><h3 id="_3-工作原理" tabindex="-1">3. 工作原理 <a class="header-anchor" href="#_3-工作原理" aria-label="Permalink to &quot;3. 工作原理&quot;">​</a></h3><p>按钮按下,内部触头动作;松手后靠<strong>复位弹簧</strong>恢复原状(所以按钮是&quot;按下有效、松手复位&quot;,不能自己保持)。</p><blockquote><p>⚠️ 注意:普通按钮<strong>按下才有作用,松手就复位</strong>。要让电路&quot;保持&quot;通电,必须靠接触器的<strong>自锁</strong>触点(第 8.4 节讲自锁电路)。</p></blockquote><h2 id="二、行程开关-限位开关" tabindex="-1">二、行程开关(限位开关) <a class="header-anchor" href="#二、行程开关-限位开关" aria-label="Permalink to &quot;二、行程开关(限位开关)&quot;">​</a></h2><p><strong>行程开关</strong>:安装在机械运动的<strong>终点或行程位置</strong>,靠运动部件的<strong>撞块</strong>碰撞触发触头动作,实现限位、行程控制、到位检测。</p><ul><li>应用:机床工作台的限位、电梯到层、起重机械限位;</li><li>相当于&quot;机械自己按下的按钮&quot;。</li></ul><h2 id="三、万能转换开关" tabindex="-1">三、万能转换开关 <a class="header-anchor" href="#三、万能转换开关" aria-label="Permalink to &quot;三、万能转换开关&quot;">​</a></h2><p><strong>万能转换开关</strong>:多挡位切换的手动开关,可以在多个位置间转换,用于切换控制方式、电路工作状态等。</p><h2 id="四、刀开关" tabindex="-1">四、刀开关 <a class="header-anchor" href="#四、刀开关" aria-label="Permalink to &quot;四、刀开关&quot;">​</a></h2><p><strong>刀开关(闸刀开关)</strong>:结构最简单的手动开关,用于<strong>隔离电源</strong>(检修时明显断开)。</p><ul><li>只用于<strong>不频繁操作</strong>、容量较小的场合;</li><li><strong>不能带负荷通断大电流</strong>(没有灭弧能力或灭弧能力弱),主要作<strong>隔离开关</strong>;</li><li>用刀开关断开电路时,若带大负荷,会产生强烈电弧,很危险。</li></ul><blockquote><p>⚠️ 判断题常考:<strong>刀开关不能带负荷操作</strong>;刀开关主要作隔离用。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 常开按钮=启动(绿),常闭按钮=停止(红);&quot;红停绿启&quot;。</li><li>✅ 按钮按下有效、松手复位,靠弹簧复位。</li><li>✅ 行程开关靠机械撞块触发,用于限位。</li><li>✅ 刀开关作隔离开关,不能带负荷通断。</li><li>⚠️ 易混点:行程开关(机械触发)vs 按钮(人按触发)。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>主令电器是&quot;发命令&quot;的:按钮给人按、行程开关给机械碰、转换开关给手拨。</li><li>按钮&quot;红停绿启、松手复位&quot;;行程开关靠撞块;刀开关作隔离、不能带负荷。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)启动按钮一般使用()颜色。 A. 红色　B. 绿色　C. 黄色　D. 黑色</li><li>(判断)停止按钮使用常闭触点,按下时电路断开。( )</li><li>(单选)靠机械撞块触发,用于限位控制的主令电器是()。 A. 按钮　B. 行程开关　C. 刀开关　D. 熔断器</li><li>(判断)刀开关可以带大负荷通断电路。( )</li><li>(判断)普通按钮松手后靠弹簧复位,不能自行保持接通状态。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。绿色按钮表示启动,红色按钮表示停止/急停。</li><li><strong>√</strong>。常闭按钮按下断开,实现停止。</li><li><strong>B</strong>。行程开关靠机械撞块触发。</li><li><strong>×</strong>。刀开关主要作隔离,不能带负荷通断大电流。</li><li><strong>√</strong>。按钮按下有效、松手复位,保持靠接触器自锁。</li></ol></details>',29)])])}const q=a(i,[["render",e]]);export{c as __pageData,q as default};
